Below is a compact, self‑contained C++ example that demonstrates the three most common smart pointers in the standard library:

* `std::unique_ptr` – exclusive ownership, cannot be copied, but can be moved.
* `std::shared_ptr` – reference‑counted shared ownership.  The object is destroyed when the last `shared_ptr` goes out of scope.
* `std::weak_ptr` – a non‑owning observer that can be used to break reference‑cycles or to check whether the object still exists.

The code uses a small `Node` class that prints messages from its constructor and destructor so you can see exactly when the object is created and destroyed.

```cpp
// smart_pointers_demo.cpp
#include <iostream>
#include <memory>
#include <vector>

struct Node
{
    int id;
    Node(int i) : id(i) { std::cout << "Node " << id << " constructed\n"; }
    ~Node() { std::cout << "Node " << id << " destroyed\n"; }
};

/* ------------- unique_ptr demo ----------------- */
void unique_ptr_demo()
{
    std::cout << "\n--- unique_ptr_demo ---\n";
    // create a Node owned exclusively by this unique_ptr
    std::unique_ptr<Node> up1 = std::make_unique<Node>(1);

    // we can move it to another unique_ptr (ownership transfer)
    std::unique_ptr<Node> up2 = std::move(up1);

    // up1 is now null
    if (!up1) std::cout << "up1 is null after move\n";

    // up2 will automatically delete the Node when it goes out of scope
}

/* ------------- shared_ptr demo ----------------- */
void shared_ptr_demo()
{
    std::cout << "\n--- shared_ptr_demo ---\n";
    // shared_ptrs share ownership; the Node is destroyed when the last shared_ptr is destroyed
    std::shared_ptr<Node> sp1 = std::make_shared<Node>(2);

    {
        std::shared_ptr<Node> sp2 = sp1;          // copy – increases refcount
        std::shared_ptr<Node> sp3 = sp1;          // copy again
        std::cout << "Reference count inside block: "
                  << sp1.use_count() << '\n';    // should be 3
    } // sp2 & sp3 go out of scope, refcount drops to 1

    std::cout << "Reference count after block: "
              << sp1.use_count() << '\n';        // should be 1

    // When sp1 goes out of scope, Node 2 will be destroyed automatically
}

/* ------------- weak_ptr demo ------------------- */
void weak_ptr_demo()
{
    std::cout << "\n--- weak_ptr_demo ---\n";
    std::shared_ptr<Node> sp = std::make_shared<Node>(3);

    // Create a weak_ptr that observes the same Node but does not own it
    std::weak_ptr<Node> wp = sp;

    std::cout << "Use count (should be 1): " << sp.use_count() << '\n';
    std::cout << "Expiring shared_ptr\n";

    // Destroy the shared_ptr
    sp.reset();

    // wp can now be checked – it is expired
    if (auto locked = wp.lock()) {
        std::cout << "Node still alive, id = " << locked->id << '\n';
    } else {
        std::cout << "Node no longer exists (wp expired)\n";
    }
}

/* ------------- custom deleter demo -------------- */
void custom_deleter_demo()
{
    std::cout << "\n--- custom_deleter_demo ---\n";

    // custom deleter that prints a message
    auto deleter = [](Node* p) {
        std::cout << "Custom deleter called for Node " << p->id << '\n';
        delete p;
    };

    std::unique_ptr<Node, decltype(deleter)> up(
        new Node(4), deleter);

    // up will call deleter when it goes out of scope
}

int main()
{
    unique_ptr_demo();
    shared_ptr_demo();
    weak_ptr_demo();
    custom_deleter_demo();

    std::cout << "\n--- program finished ---\n";
    return 0;
}
```

### What to expect when you run it

```
--- unique_ptr_demo ---

--- shared_ptr_demo ---
Reference count inside block: 3
Reference count after block: 1
Node 2 destroyed

--- weak_ptr_demo ---
Node 3 constructed
Use count (should be 1): 1
Expiring shared_ptr
Node 3 destroyed
Node no longer exists (wp expired)

--- custom_deleter_demo ---
Node 4 constructed
Custom deleter called for Node 4
Node 4 destroyed

--- program finished ---
```

### Key take‑aways

| Pointer type | Ownership model | When the object is destroyed | Typical use‑case |
|--------------|-----------------|------------------------------|-----------------|
| `unique_ptr` | Exclusive | When the `unique_ptr` goes out of scope or is reset | Lightweight RAII, owning a single resource |
| `shared_ptr` | Reference counted | When the last `shared_ptr` is destroyed | Shared ownership, e.g., shared data structures |
| `weak_ptr`   | Non‑owning | Never destroys the object | Observing an object without influencing its lifetime; breaking cycles |

Feel free to tweak the example to suit your own projects or to explore more advanced patterns such as `shared_from_this`, `enable_shared_from_this`, or custom allocators. Happy coding!
